-- -----------------------------------
-- Table structure for `email_send_reports`
-- -----------------------------------

DROP TABLE IF EXISTS `email_send_reports`;
CREATE TABLE `email_send_reports` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `subject` varchar(255) NOT NULL,
  `last_communication` datetime NOT NULL,
  `hour_hit` int(11) NOT NULL,
  `today_date` date NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=186 DEFAULT CHARSET=latin1;

